word = input()
found = []
with open("story.txt", "r", encoding="utf-8") as f:
    for num, line in enumerate(f, 1):
        line = line.rstrip("\n")
        if word in line:
            found.append(f"{num}: {line}")

if found:
    for item in found:
        print(item)
    print(f"총 {len(found)}줄")
else:
    print("찾을 수 없습니다")
